# Env diagnosis
ls -la /tmp/.git 2>&1 | head -5
node -v
# Instrument the failing case briefly on release worktree
RELEASE_WT=$(ls -d /tmp/nexus-release-check-* | tail -1)
cd "$RELEASE_WT/cli"
HOME=$(mktemp -d) node --import tsx <<'EOF' 2>&1 | tail -40
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execSync } from 'node:child_process';
import { AutonomousAgent } from './src/agent.js';
import { DEFAULT_CONTINUATION, HarnessConfig } from './src/types.js';
import { startGateway, Reply } from './test/helpers/fixtures.js';

const quiet = (agent) => { (agent).ui = new Proxy({}, { get: () => () => {} }); return agent; };
const PKG = JSON.stringify({ name: 'x', version: '1.0.0', private: true, main: './math.js', scripts: { test: 'env -u NODE_TEST_CONTEXT node --test test/*.test.js' } });
const ADD_BUGGY = 'exports.add = (a, b) => a - b;\n';
const ADD_FIXED = 'exports.add = (a, b) => a + b;\n';
const ADD_TEST = 'const test = require("node:test");\nconst assert = require("node:assert/strict");\nconst { add } = require("../math.js");\ntest("adds", () => assert.equal(add(2, 3), 5));\n';

const root = fs.mkdtempSync(path.join(os.tmpdir(), 'nexus-probe-'));
for (const [name, content] of Object.entries({ 'package.json': PKG, 'math.js': ADD_BUGGY, 'test/math.test.js': ADD_TEST })) {
  fs.mkdirSync(path.dirname(path.join(root, name)), { recursive: true });
  fs.writeFileSync(path.join(root, name), content);
}
execSync('git init -q && git config user.name t && git config user.email t@t.invalid && git add . && git commit -qm base', { cwd: root, stdio: 'ignore' });

const gw = await startGateway((n) => {
  if (n === 1) return { kind: 'tools', calls: [{ name: 'write_file', args: { path: 'math.js', content: ADD_FIXED, overwrite: true } }] };
  if (n === 2) return { kind: 'tools', calls: [{ name: 'task_completed', args: { summary: 'done' } }] };
  return { kind: 'text', content: 'done' };
});
const cfg = { endpoint: gw.url, model: 'm', maxSteps: 30, temperature: 0, workspace: root, shell: 'bash', approvalMode: 'auto', fullAccess: true, continuation: { ...DEFAULT_CONTINUATION, maxCompletionNudges: 0 }, trustedDeliverableFiles: ['math.js'] };
const agent = quiet(new AutonomousAgent(cfg));
try {
  const turn = await agent.runTurn('npm test fails; fix math.js.');
  console.log(JSON.stringify({ outcome: turn.outcome, detail: turn.detail, verification: turn.verification, status: turn.status }, null, 2));
} finally {
  agent.shutdown();
  await gw.close();
  fs.rmSync(root, { recursive: true, force: true });
}
EOF

