          const found = reference(value);
          if (typeof found === "object") return refuse(`argument ${shown}: ${found.problem}`);
        }
      }
    }
  }
  return { files: [...covered].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)).map(([name, sha256]) => ({ path: name, sha256 })) };
}

