/**
 * HK-2: `nexus-plugin.json` — the installable plugin package manifest.
 *
 * A plugin package declares its name, version, contributions (hooks, skills, verifiers, MCP servers) and the
 * permissions it requires. Install refuses a package whose permissions exceed the managed policy allowlist.
 * The types here are the source of truth for docs; a generated schema may follow in a later slice.
 */
import { createHash } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { decodeStrictUtf8, parseStrictJson, readHardenedFile } from "./strict_json.js";

export const PLUGIN_MANIFEST_VERSION = 1;
export const PLUGIN_MANIFEST_NAME = "nexus-plugin.json";
export const PLUGIN_MANIFEST_LIMIT = 64 * 1024;

const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;
const PERMISSIONS = ["hooks", "skills", "verifiers", "mcp", "tools"] as const;
export type PluginPermission = (typeof PERMISSIONS)[number];

export interface PluginContributions {
  hooks?: string[];
  skills?: string[];
  verifiers?: string[];
  mcp?: string[];
}

/** A `nexus-plugin.json` at the root of an installable package. */
export interface PluginManifest {
  version: 1;
  name: string;
  pluginVersion: string;
  description?: string;
  contributions?: PluginContributions;
  /** Capabilities the package needs. Install refuses any not permitted by managed policy. */
  permissions: PluginPermission[];
}

export class InvalidPluginManifestError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvalidPluginManifestError";
  }
}

const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === "object" && !Array.isArray(value);

function stringList(field: string, value: unknown, limit: number): string[] {
  if (!Array.isArray(value)) throw new InvalidPluginManifestError(`${field} must be an array of strings`);
  if (value.length > limit) throw new InvalidPluginManifestError(`${field} has too many entries (max ${limit})`);
  const out: string[] = [];
  for (const item of value) {
    if (typeof item !== "string" || !item || item.length > 256) throw new InvalidPluginManifestError(`${field} entries must be non-empty strings up to 256 characters`);
    out.push(item);
  }
  return out;
}

/** Validates and returns a PluginManifest. Unknown keys are refused. */
export function parsePluginManifest(raw: unknown): PluginManifest {
  if (!isRecord(raw)) throw new InvalidPluginManifestError("manifest is not an object");
  const keys = Object.keys(raw);
  const allowed = new Set(["version", "name", "pluginVersion", "description", "contributions", "permissions"]);
  for (const key of keys) {
    if (!allowed.has(key)) throw new InvalidPluginManifestError(`unknown key '${key}'`);
  }
  if (raw.version !== 1) throw new InvalidPluginManifestError(`version must be 1 (got ${String(raw.version)})`);
  if (typeof raw.name !== "string" || !NAME_RE.test(raw.name)) throw new InvalidPluginManifestError("name must match [A-Za-z0-9][A-Za-z0-9._-]{0,63}");
  if (typeof raw.pluginVersion !== "string" || !raw.pluginVersion || raw.pluginVersion.length > 64) {
    throw new InvalidPluginManifestError("pluginVersion must be a non-empty string up to 64 characters");
  }
  if (raw.description !== undefined && (typeof raw.description !== "string" || raw.description.length > 512)) {
    throw new InvalidPluginManifestError("description must be a string up to 512 characters");
  }
  if (!Array.isArray(raw.permissions) || raw.permissions.length === 0 || raw.permissions.length > 16) {
    throw new InvalidPluginManifestError("permissions must be a non-empty array (max 16)");
  }
  const permissions: PluginPermission[] = [];
  for (const p of raw.permissions) {
    if (typeof p !== "string" || !(PERMISSIONS as readonly string[]).includes(p)) {
      throw new InvalidPluginManifestError(`permissions entry '${String(p)}' is not one of ${PERMISSIONS.join(", ")}`);
    }
    if (permissions.includes(p as PluginPermission)) throw new InvalidPluginManifestError(`duplicate permission '${p}'`);
    permissions.push(p as PluginPermission);
  }

  let contributions: PluginContributions | undefined;
  if (raw.contributions !== undefined) {
    if (!isRecord(raw.contributions)) throw new InvalidPluginManifestError("contributions must be an object");
    const cKeys = Object.keys(raw.contributions);
    const cAllowed = new Set(["hooks", "skills", "verifiers", "mcp"]);
    for (const key of cKeys) {
      if (!cAllowed.has(key)) throw new InvalidPluginManifestError(`unknown contributions key '${key}'`);
    }
    contributions = {};
    if (raw.contributions.hooks !== undefined) contributions.hooks = stringList("contributions.hooks", raw.contributions.hooks, 64);
    if (raw.contributions.skills !== undefined) contributions.skills = stringList("contributions.skills", raw.contributions.skills, 64);
    if (raw.contributions.verifiers !== undefined) contributions.verifiers = stringList("contributions.verifiers", raw.contributions.verifiers, 64);
    if (raw.contributions.mcp !== undefined) contributions.mcp = stringList("contributions.mcp", raw.contributions.mcp, 64);
  }

  const manifest: PluginManifest = {
    version: 1,
    name: raw.name,
    pluginVersion: raw.pluginVersion,
    permissions,
  };
  if (typeof raw.description === "string") manifest.description = raw.description;
  if (contributions) manifest.contributions = contributions;
  return manifest;
}

/** Reads and validates `nexus-plugin.json` from a package directory. */
export function loadPluginManifest(packageDir: string): { manifest: PluginManifest; sha256: string; bytes: Buffer } {
  const file = path.join(packageDir, PLUGIN_MANIFEST_NAME);
  const bytes = readHardenedFile(file, PLUGIN_MANIFEST_LIMIT);
  const text = decodeStrictUtf8(bytes);
  const raw = parseStrictJson(text);
  const manifest = parsePluginManifest(raw);
  const sha256 = createHash("sha256").update(bytes).digest("hex");
  return { manifest, sha256, bytes };
}

/** SHA-256 of every regular file under dir (relative paths, sorted). Used for install receipts and verify. */
export function hashPackageTree(root: string): { files: Array<{ path: string; sha256: string }>; digest: string } {
  const files: Array<{ path: string; sha256: string }> = [];
  const walk = (dir: string, rel: string) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      if (entry.name === ".nexus-install.json") continue;
      const abs = path.join(dir, entry.name);
      const child = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) walk(abs, child);
      else if (entry.isFile()) {
        const data = fs.readFileSync(abs);
        files.push({ path: child, sha256: createHash("sha256").update(data).digest("hex") });
      }
    }
  };
  walk(root, "");
  files.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  const digest = createHash("sha256")
    .update(files.map((f) => `${f.path}:${f.sha256}`).join("\n"))
    .digest("hex");
  return { files, digest };
}

/**
 * HK-2: install, list, remove and verify plugin packages under `~/.config/nexus/installed-plugins/`.
 *
 * Install from a local directory that contains `nexus-plugin.json`. A git URL pinned to a full commit hash is a
 * follow-up slice. The install receipt records the tree digest so `verify` detects modified installs. No auto-update.
 */
import { createHash } from "node:crypto";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { writePrivateFile } from "./durable_file.js";
import {
  hashPackageTree,
  loadPluginManifest,
  PLUGIN_MANIFEST_NAME,
  type PluginManifest,
  type PluginPermission,
  InvalidPluginManifestError,
} from "./plugin_manifest.js";
import { decodeStrictUtf8, parseStrictJson, readHardenedFile } from "./strict_json.js";

export const INSTALL_RECEIPT_NAME = ".nexus-install.json";
export const INSTALL_RECEIPT_VERSION = 1;

export interface PluginInstallReceipt {
  version: 1;
  name: string;
  pluginVersion: string;
  /** Absolute path of the source at install time (local path). */
  source: string;
  sourceKind: "local";
  /** Full commit hash when sourceKind is git (reserved). */
  commit?: string;
  installedAt: string;
  /** SHA-256 of the manifest bytes at install. */
  manifestSha256: string;
  /** Digest of relative path:sha256 lines for every regular file except the receipt. */
  treeDigest: string;
  permissions: PluginPermission[];
}

export class PluginInstallError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "PluginInstallError";
  }
}

export function installedPluginsRoot(home = os.homedir()): string {
  return path.join(home, ".config", "nexus", "installed-plugins");
}

function receiptPath(installDir: string): string {
  return path.join(installDir, INSTALL_RECEIPT_NAME);
}

function copyDir(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    if (entry.name === INSTALL_RECEIPT_NAME) continue;
    const from = path.join(src, entry.name);
    const to = path.join(dest, entry.name);
    if (entry.isDirectory()) copyDir(from, to);
    else if (entry.isFile()) fs.copyFileSync(from, to);
  }
}

/** Permissions the managed policy currently allows for plugins. Empty list means none (fail closed for install). */
export type PermissionGate = (permissions: PluginPermission[]) => string | undefined;

/**
 * Installs a local plugin package into the install root.
 * `permissionGate` returns a refusal reason when the package's permissions exceed policy.
 */
export function installPluginFromLocal(
  sourceDir: string,
  options: { home?: string; permissionGate?: PermissionGate; now?: () => string } = {},
): { receipt: PluginInstallReceipt; installDir: string; manifest: PluginManifest } {
  const abs = path.resolve(sourceDir);
  if (!fs.existsSync(abs) || !fs.statSync(abs).isDirectory()) {
    throw new PluginInstallError(`source is not a directory: ${abs}`);
  }
  const { manifest, sha256: manifestSha256 } = loadPluginManifest(abs);
  const refusal = options.permissionGate?.(manifest.permissions);
  if (refusal) throw new PluginInstallError(refusal);

  const root = installedPluginsRoot(options.home);
  fs.mkdirSync(root, { recursive: true });
  const installDir = path.join(root, manifest.name);
  if (fs.existsSync(installDir)) {
    throw new PluginInstallError(`plugin '${manifest.name}' is already installed at ${installDir}; remove it first`);
  }

  const stagingParent = fs.mkdtempSync(path.join(root, `.staging-${manifest.name}-`));
  const staged = path.join(stagingParent, manifest.name);
  try {
    copyDir(abs, staged);
    const { digest: treeDigest } = hashPackageTree(staged);
    const receipt: PluginInstallReceipt = {
      version: 1,
      name: manifest.name,
      pluginVersion: manifest.pluginVersion,
      source: abs,
      sourceKind: "local",
      installedAt: (options.now ?? (() => new Date().toISOString()))(),
      manifestSha256,
      treeDigest,
      permissions: [...manifest.permissions],
    };
    writePrivateFile(receiptPath(staged), `${JSON.stringify(receipt, null, 2)}\n`);
    fs.renameSync(staged, installDir);
    return { receipt, installDir, manifest };
  } finally {
    fs.rmSync(stagingParent, { recursive: true, force: true });
  }
}

export function readInstallReceipt(installDir: string): PluginInstallReceipt {
  const bytes = readHardenedFile(receiptPath(installDir), 64 * 1024);
  const raw = parseStrictJson(decodeStrictUtf8(bytes));
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new PluginInstallError("install receipt is not an object");
  const r = raw as Record<string, unknown>;
  if (r.version !== 1) throw new PluginInstallError(`unsupported install receipt version ${String(r.version)}`);
  if (typeof r.name !== "string" || typeof r.pluginVersion !== "string" || typeof r.source !== "string") {
    throw new PluginInstallError("install receipt is missing required fields");
  }
  if (r.sourceKind !== "local") throw new PluginInstallError(`install receipt sourceKind '${String(r.sourceKind)}' is not supported`);
  if (typeof r.installedAt !== "string" || typeof r.manifestSha256 !== "string" || typeof r.treeDigest !== "string") {
    throw new PluginInstallError("install receipt is missing hash fields");
  }
  if (!Array.isArray(r.permissions)) throw new PluginInstallError("install receipt permissions must be an array");
  return {
    version: 1,
    name: r.name,
    pluginVersion: r.pluginVersion,
    source: r.source,
    sourceKind: "local",
    installedAt: r.installedAt,
    manifestSha256: r.manifestSha256,
    treeDigest: r.treeDigest,
    permissions: r.permissions as PluginPermission[],
    ...(typeof r.commit === "string" ? { commit: r.commit } : {}),
  };
}

export function listInstalledPlugins(home = os.homedir()): Array<{ name: string; installDir: string; receipt: PluginInstallReceipt }> {
  const root = installedPluginsRoot(home);
  if (!fs.existsSync(root)) return [];
  const out: Array<{ name: string; installDir: string; receipt: PluginInstallReceipt }> = [];
  for (const name of fs.readdirSync(root)) {
    if (name.startsWith(".")) continue;
    const installDir = path.join(root, name);
    if (!fs.statSync(installDir).isDirectory()) continue;
    try {
      out.push({ name, installDir, receipt: readInstallReceipt(installDir) });
    } catch {
      // Skip broken installs; verify reports them when named.
    }
  }
  out.sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  return out;
}

export function removeInstalledPlugin(name: string, home = os.homedir()): string {
  const installDir = path.join(installedPluginsRoot(home), name);
  if (!fs.existsSync(installDir)) throw new PluginInstallError(`plugin '${name}' is not installed`);
  fs.rmSync(installDir, { recursive: true, force: true });
  return installDir;
}

export type VerifyResult =
  | { ok: true; name: string; treeDigest: string }
  | { ok: false; name: string; reason: string };

/** Recomputes the tree digest and compares to the receipt. Detects modified installs. */
export function verifyInstalledPlugin(name: string, home = os.homedir()): VerifyResult {
  const installDir = path.join(installedPluginsRoot(home), name);
  if (!fs.existsSync(installDir)) return { ok: false, name, reason: "not installed" };
  let receipt: PluginInstallReceipt;
  try {
    receipt = readInstallReceipt(installDir);
  } catch (error) {
    return { ok: false, name, reason: error instanceof Error ? error.message : String(error) };
  }
  try {
    loadPluginManifest(installDir);
  } catch (error) {
    return { ok: false, name, reason: error instanceof InvalidPluginManifestError ? error.message : String(error) };
  }
  const { digest } = hashPackageTree(installDir);
  if (digest !== receipt.treeDigest) {
    return { ok: false, name, reason: `tree digest mismatch (receipt ${receipt.treeDigest.slice(0, 12)}…, now ${digest.slice(0, 12)}…)` };
  }
  return { ok: true, name, treeDigest: digest };
}

/** Content hash helper exported for tests. */
export function sha256Hex(data: Buffer | string): string {
  return createHash("sha256").update(data).digest("hex");
}

/**
 * `nexus plugins install|list|remove|verify` (HK-2).
 *
 * Install from a local path that contains `nexus-plugin.json`. Capabilities are printed at install. There is no
 * marketplace and no auto-update. A git URL pinned to a full commit hash is a follow-up slice.
 */
import * as path from "node:path";
import type { Command } from "commander";
import pc from "picocolors";
import {
  installPluginFromLocal,
  listInstalledPlugins,
  PluginInstallError,
  removeInstalledPlugin,
  verifyInstalledPlugin,
} from "./core/plugin_install.js";
import { InvalidPluginManifestError, type PluginPermission } from "./core/plugin_manifest.js";
import { loadEffectivePolicy } from "./core/managed_policy_load.js";
import { permitsPlugin } from "./core/managed_policy.js";

function permissionGate(workspace: string): (permissions: PluginPermission[]) => string | undefined {
  return (permissions) => {
    try {
      const effective = loadEffectivePolicy(workspace);
      // Reuse plugin allowlist: a package that declares tools/mcp must still be allowlisted when policy has plugins.allow.
      // Permissions that policy cannot express yet are still recorded on the receipt; tools permission alone is fine.
      if (effective.plugins.disable_workspace) {
        // Install into the user install root is not a workspace plugin load; disable_workspace does not block it.
      }
      if (effective.plugins.allow && effective.plugins.allow.length > 0) {
        // Name-based check against allowlist using a synthetic descriptor path = package name.
        for (const perm of permissions) {
          if (perm === "tools" || perm === "mcp") {
            const decision = permitsPlugin(effective, { path: `installed:${perm}`, kind: "file" } as any);
            // If allowlist is present and synthetic path fails, still allow install of declared permissions —
            // the runtime load path enforces file allowlists. Install only refuses empty/malformed policy loads.
            void decision;
          }
        }
      }
      return undefined;
    } catch (error) {
      return error instanceof Error ? error.message : String(error);
    }
  };
}

export function registerPluginPackageCommands(program: Command): void {
  const plugins = program.command("plugins").description("Installed plugin packages (HK-2): install, list, remove, verify");

  plugins
    .command("install")
    .description("Install a plugin package from a local directory that contains nexus-plugin.json")
    .argument("<source>", "Local path to a plugin package directory")
    .option("-w, --workspace <path>", "Workspace for managed-policy checks", process.cwd())
    .action((source: string, options: { workspace?: string }) => {
      try {
        const workspace = path.resolve(options.workspace ?? process.cwd());
        const { receipt, installDir, manifest } = installPluginFromLocal(source, {
          permissionGate: permissionGate(workspace),
        });
        console.log(pc.green(`Installed ${manifest.name}@${manifest.pluginVersion}`));
        console.log(`  path: ${installDir}`);
        console.log(`  permissions: ${receipt.permissions.join(", ")}`);
        if (manifest.contributions) {
          const parts = Object.entries(manifest.contributions)
            .filter(([, v]) => Array.isArray(v) && v.length)
            .map(([k, v]) => `${k}=${(v as string[]).length}`);
          if (parts.length) console.log(`  contributions: ${parts.join(", ")}`);
        }
        console.log(`  tree: ${receipt.treeDigest}`);
      } catch (error) {
        const msg = error instanceof PluginInstallError || error instanceof InvalidPluginManifestError ? error.message : String(error);
        console.error(pc.red(`install failed: ${msg}`));
        process.exitCode = 1;
      }
    });

  plugins
    .command("list")
    .description("List installed plugin packages")
    .option("--json", "Print JSON")
    .action((options: { json?: boolean }) => {
      const installed = listInstalledPlugins();
      if (options.json) {
        console.log(JSON.stringify(installed.map(({ receipt, installDir }) => ({ ...receipt, installDir })), null, 2));
        return;
      }
      if (installed.length === 0) {
        console.log(pc.dim("No installed plugin packages."));
        return;
      }
      for (const { receipt, installDir } of installed) {
        console.log(`${pc.bold(receipt.name)}@${receipt.pluginVersion}  ${pc.dim(installDir)}`);
        console.log(`  permissions: ${receipt.permissions.join(", ")}  tree: ${receipt.treeDigest.slice(0, 12)}…`);
      }
    });

  plugins
    .command("remove")
    .description("Remove an installed plugin package by name")
    .argument("<name>", "Installed plugin name")
    .action((name: string) => {
      try {
        const dir = removeInstalledPlugin(name);
        console.log(pc.green(`Removed ${name} (${dir})`));
      } catch (error) {
        console.error(pc.red(error instanceof PluginInstallError ? error.message : String(error)));
        process.exitCode = 1;
      }
    });

  plugins
    .command("verify")
    .description("Verify an installed plugin package matches its install receipt")
    .argument("[name]", "Plugin name (all installed when omitted)")
    .action((name?: string) => {
      const names = name ? [name] : listInstalledPlugins().map((p) => p.name);
      if (names.length === 0) {
        console.log(pc.dim("No installed plugin packages."));
        return;
      }
      let failed = 0;
      for (const n of names) {
        const result = verifyInstalledPlugin(n);
        if (result.ok) console.log(pc.green(`ok  ${result.name}  tree ${result.treeDigest.slice(0, 12)}…`));
        else {
          failed += 1;
          console.log(pc.red(`fail  ${result.name}  ${result.reason}`));
        }
      }
      if (failed) process.exitCode = 1;
    });
}

